import { Link, useNavigate } from "react-router-dom";
import { useState, useEffect, useRef } from "react";
import axios from "axios";
import hashids from "../utils/hashids";
import { FiSearch } from "react-icons/fi";

const PopularOne = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    const delayDebounceFn = setTimeout(() => {
      if (query.trim().length > 2) {
        handleSearch(query);
      } else {
        setResults([]);
        setShowDropdown(false);
      }
    }, 500);

    return () => clearTimeout(delayDebounceFn);
  }, [query]);

  const handleSearch = async (searchTerm) => {
    setIsLoading(true);
    try {
      const response = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/centres/global-search?query=${searchTerm}`
      );
      setResults(response.data);
      setShowDropdown(true);
    } catch (error) {
      console.error("Search failed:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const safeEncodeId = (id) => {
    return hashids.safeEncodeHex(id);
  };

  const getResultLink = (item) => {
    const id = safeEncodeId(item._id);
    if (item.type === "centre") return `/centre/${item.centreSlug}/${id}`;
    if (item.type === "service") return `/service/${item.serviceSlug}/${id}`;
    if (item.type === "package") return `/package/${item.packageSlug}/${id}`;
    return "#";
  };

  const getResultTitle = (item) => {
    if (item.type === "centre") return item.centreName;
    if (item.type === "service") return item.serviceName;
    if (item.type === "package") return item.packageName;
    return "";
  };

  const getCategoryLabel = (type) => {
    if (type === "centre") return "Healthcare Center";
    if (type === "service") return "Service";
    if (type === "package") return "Package";
    return "";
  };
  const categories = [
    {
      label: "Doctor Consultation",
      image: "/assets/images/categories/Webp/OPD-Consultations1.webp",
    },
    {
      label: "Vaccination Services",
      image: "/assets/images/categories/Webp/Vaccinations1.webp",
    },
    {
      label: "Lab and Diagnostic",
      image: "/assets/images/categories/Webp/Diagnostics1.webp",
    },
    {
      label: "Operative Procedures",
      image: "/assets/images/categories/Webp/Operative-Procedures1.webp",
    },
    {
      label: "Health Checkup Packages",
      image: "/assets/images/categories/Webp/Health-Check1.webp",
    },
    {
      label: "Non Surgical",
      image: "/assets/images/categories/Webp/Non-surgical1.webp",
    },
  ];

  return (
    <section className="popular pb-60 pt-0">
      <div className="container container-two">
        {/* <div className="section-heading mb-30 text-center">
          <h2
            className="section-heading__title"
            style={{ fontFamily: "inter", fontSize: "30px" }}
          >
            Explore Top Healthcare Services & Medical Solutions
          </h2>

          <p
            style={{
              maxWidth: "700px",
              margin: "10px auto 0",
              lineHeight: "1.6",
              fontSize: "16px",
              color: "#555"
            }}
          >
            Find a wide range of healthcare services, including doctor consultations,
            lab tests, vaccination, and health checkup packages to meet all your
            medical needs in one place.
          </p>
        </div> */}

        {/* Global Search Bar */}
        <div className="search-section py-3 d-flex justify-content-center">
          <div className="search-box-modern position-relative w-100" style={{ maxWidth: '850px' }} ref={dropdownRef}>
            <div className="input-group-modern d-flex align-items-center w-100">
              <div className="input-wrapper d-flex align-items-center flex-grow-1 position-relative">
                <i className="fas fa-search search-icon-modern"></i>
                <input
                  type="text"
                  className="search-input-modern w-100"
                  placeholder="Search for Lab Tests, Consultations, Vaccinations ..."
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  onFocus={() => query.length > 2 && setShowDropdown(true)}
                />
                {isLoading && (
                  <div className="spinner-border spinner-border-sm text-primary position-absolute" style={{ right: '10px' }} role="status">
                    <span className="visually-hidden">Loading...</span>
                  </div>
                )}
              </div>
              {/* <button className="search-btn-modern" onClick={() => handleSearch(query)}>
               <FiSearch size={20} />
              </button> */}
                <button
                              type="submit" onClick={() => handleSearch(query)}
                              style={{
                                backgroundColor: '#3579F3',
                                color: 'white',
                                border: 'none',
                                borderRadius: '50%',
                                width: '44px',
                                height: '44px',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                cursor: 'pointer',
                                flexShrink: 0,
                                transition: 'all 0.2s ease'
                              }}
                            >
                              <FiSearch size={20} />
                            </button>
            </div>

            {/* Suggestions Dropdown */}
            {showDropdown && results.length > 0 && (
              <div className="search-suggestions shadow-lg">
                {results.map((item, index) => (
                  <Link
                    key={index}
                    to={getResultLink(item)}
                    className="suggestion-item d-flex align-items-center gap-3 p-3 text-decoration-none"
                    onClick={() => setShowDropdown(false)}
                  >
                    <div className="suggestion-icon">
                      {item.type === "centre" && <i className="fas fa-hospital text-primary"></i>}
                      {item.type === "service" && <i className="fas fa-microscope text-success"></i>}
                      {item.type === "package" && <i className="fas fa-box-open text-warning"></i>}
                    </div>
                    <div className="suggestion-info flex-grow-1">
                      <div className="suggestion-title fw-600 text-heading">{getResultTitle(item)}</div>
                      <div className="suggestion-subtitle text-muted small">
                        {item.type === "centre" ? `${item.city || ''} ${item.centreType || ''}` : item.centre?.centreName}
                      </div>
                    </div>
                    <div className="suggestion-tag badge bg-light text-muted fw-normal">
                      {getCategoryLabel(item.type)}
                    </div>
                  </Link>
                ))}
              </div>
            )}

            {showDropdown && query.length > 2 && results.length === 0 && !isLoading && (
              <div className="search-suggestions p-4 text-center text-muted">
                No results found for "{query}"
              </div>
            )}
          </div>
        </div>

        <div className="categories-wrapper"
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            padding: "0px 0px",
            marginBottom: "50px"
          }}
        >
          <div className="popular_Cat"
            style={{
              display: "flex",
              gap: "20px",
              maxWidth: "1400px",
              flexWrap: "nowrap",
              justifyContent: "center",
            }}
          >
            {categories.map((item, index) => (
              <Link
                key={index}
                to={
                  item.label === "Health Checkup Packages"
                    ? "/all-package"
                    : `/all-service?category=${encodeURIComponent(item.label)}`
                }
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  width: "200px",
                  textAlign: "center",
                  textDecoration: "none",
                  color: "inherit",
                }}
              >
                <img className="popular_img"
                  src={item.image}
                  alt=""
                  width="200"
                  height="120"
                  style={{
                    width: "100%",
                    height: "120px",
                    objectFit: "cover",
                    borderRadius: "8px",
                  }}
                  loading="lazy"
                />
                <span className="popular_label"
                  style={{
                    marginTop: "5px",
                    fontWeight: "600",
                    fontSize: "14px",
                  }}
                >
                  {item.label}
                </span>
              </Link>
            ))}
          </div>
        </div>

        {/* <div className="popular__button text-center mb-3">
          <Link
            to="/all-service"
            className="font-18 fw-600 text-heading hover-text-main text-decoration-underline font-heading"
            style={{ fontFamily: "inter" }}
          >
            Explore More
          </Link>
        </div> */}
      </div>
      <style>
        {
          `.search-section {
            position: relative;
            z-index: 1000;
          }
          .search-box-modern {
            position: relative;
            z-index: 1000;
            padding: 5px;
          }
          .input-group-modern {
            background: #fff;
            padding: 6px;
            border-radius: 50px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.08);
            border: 1px solid rgba(0,0,0,0.05);
            transition: all 0.3s ease;
          }
          .input-group-modern:focus-within {
            box-shadow: 0 15px 35px rgba(0,0,0,0.12);
            border-color: #2563eb; 
          }
          .input-wrapper {
            padding: 0 15px 0 25px;
          }
          .search-icon-modern {
            color: #94a3b8;
            font-size: 18px;
            margin-right: 12px;
          }
          .search-input-modern {
            border: none;
            outline: none;
            padding: 12px 0;
            font-size: 16px;
            color: #1e293b;
            background: transparent;
          }
          .search-input-modern::placeholder {
            color: #94a3b8;
          }
          .search-btn-modern {
            background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
            color: #fff;
            border: none;
            padding: 12px 40px;
            border-radius: 50px;
            font-weight: 600;
            font-size: 16px;
            transition: all 0.3s ease;
            box-shadow: 0 4px 12px rgba(37, 99, 235, 0.2);
          }
          .search-btn-modern:hover {
            transform: translateY(-1px);
            box-shadow: 0 6px 15px rgba(37, 99, 235, 0.3);
            background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
          }
          @media (max-width: 576px) {
            .search-btn-modern {
              padding: 10px 25px;
              font-size: 14px;
            }
            .input-wrapper {
              padding: 0 10px 0 15px;
            }
            .search-icon-modern {
              font-size: 16px;
              margin-right: 8px;
            }
            .search-input-modern {
              font-size: 14px;
            }
          }
          @media (max-width: 500px) {
            .input-group-modern {
              padding: 4px !important;
              height: 52px !important;
            }
            .search-btn-modern {
              padding: 8px 18px !important;
              font-size: 13px !important;
              white-space: nowrap !important;
            }
            .search-input-modern {
              font-size: 12px !important;
            }
            .search-icon-modern {
              font-size: 14px !important;
              margin-right: 6px !important;
            }
            .input-wrapper {
              padding: 0 8px 0 12px !important;
            }
            .search-input-modern::placeholder {
              font-size: 11px !important;
            }

            /* 3 Column Grid for Categories */
            .popular_Cat {
              flex-wrap: wrap !important;
              gap: 8px !important;
              justify-content: center !important;
            }
            .popular_Cat a {
              width: calc(33.33% - 8px) !important;
              max-width: none !important;
            }
            .popular_img {
              height: 90px !important;
              width: 100% !important;
            }
            .popular_label {
              font-size: 10px !important;
              margin-top: 5px !important;
              line-height: 1.2 !important;
            }

            .popular {
              padding-bottom: 20px !important;
            }
            .categories-wrapper {
              margin-bottom: 10px !important;
            }
            .padding-y-60 {
              padding-top: 30px !important;
              padding-bottom: 30px !important;
            }

            /* Card Spacing & Padding Optimization */
            .row.gy-4 {
              --bs-gutter-y: 10px !important;
            }
            .product-item__content {
              padding: 12px !important;
            }
            .product-item__info {
              margin-bottom: 8px !important;
            }
            .product-item__title {
              font-size: 14px !important;
              margin-bottom: 4px !important;
              min-height: auto !important;
            }
            .product-item__price {
              font-size: 15px !important;
            }
            
            /* Service Card Specific Height Reduction */
            .service-card-modern {
              height: auto !important;
              min-height: unset !important;
            }
            .doctor-info-modern {
              height: auto !important;
              min-height: unset !important;
              margin-bottom: 8px !important;
            }
            .btn-sm.pill {
              padding: 9px 12px !important;
              font-size: 12.5px !important;
              font-weight: 600 !important;
            }
            .product-item__author {
              height: auto !important;
              align-self: center !important;
              line-height: 1.2 !important;
            }
            .product-item__info {
              align-items: center !important;
              display: flex !important;
              justify-content: flex-start !important;
              gap: 10px !important;
            }
            .product-item__info > *:last-child {
              margin-left: auto !important;
            }
            .package-item__info > *:last-child {
              margin-left: 0 !important;
            }
            .product-item__author {
              max-width: 55% !important;
            }
          }
          @media(max-width:1280px){
            .popular_Cat{
             flex-wrap: wrap !important;
            justify-content: center !important;
            }
          }
          
          .search-suggestions {
            position: absolute;
            top: 100%;
            left: 0;
            right: 0;
            background: #fff;
            border-radius: 15px;
            margin-top: 10px;
            z-index: 9999;
            max-height: 400px;
            overflow-y: auto;
            border: 1px solid rgba(0,0,0,0.05);
            box-shadow: 0 10px 30px rgba(0,0,0,0.1);
          }
          
          .suggestion-item {
            transition: all 0.2s ease;
            border-bottom: 1px solid rgba(0,0,0,0.03);
          }
          
          .suggestion-item:last-child {
            border-bottom: none;
          }
          
          .suggestion-item:hover {
            background-color: #f8fafc;
          }
          
          .suggestion-icon {
            width: 40px;
            height: 40px;
            background: #f1f5f9;
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
          }
          
          .suggestion-title {
            font-size: 15px;
            color: #1e293b;
          }
          
          .suggestion-subtitle {
            font-size: 12px;
          }
          
          .suggestion-tag {
            font-size: 11px;
            padding: 5px 10px;
            border-radius: 6px;
            background: #f1f5f9 !important;
            color: #475569 !important;
            border: 1px solid #e2e8f0;
          }
          `
        }
      </style>
    </section>
  );
};

export default PopularOne;
